const task=document.querySelector('#task'),width=document.querySelector('#width'),size=document.querySelector('#size'),main=document.querySelector('main');function render(){main.replaceChildren(...['baseline','signal','folio'].map(v=>{const f=document.createElement('figure'),c=document.createElement('figcaption'),a=document.createElement('a'),i=document.createElement('img');c.textContent=({baseline:'0 · Native baseline',signal:'A · Signal',folio:'B · Folio'})[v];i.src=`${v}-${task.value}-${width.value}-${size.value}.png`;i.alt=`${v} ${task.value}, ${width.value}px viewport, ${size.value}px text`;a.href=i.src;a.target='_blank';a.rel='noopener';a.append(i);f.append(c,a);return f;}));}document.querySelector('form').addEventListener('change',render);render();
